const state={missions:[],filtered:[]}; const $=s=>document.querySelector(s); const els={status:$('#status-filter'),destination:$('#destination-filter'),search:$('#search-input'),sort:$('#sort-select'),body:$('#mission-table-body'),count:$('#result-count'),total:$('#total-missions'),active:$('#active-missions'),completed:$('#completed-missions'),countries:$('#country-count'),orbit:$('#active-orbit-count'),updated:$('#last-updated'),chart:$('#destination-chart'),dataStatus:$('#data-status'),menu:$('.menu-toggle'),nav:$('#site-nav')}; async function loadMissions(){ try{ const response=await fetch('data/missions.json', {cache:'default'}); if(!response.ok) throw new Error(`HTTP ${response.status}`); const data=await response.json(); if(!Array.isArray(data.missions)) throw new Error('Invalid dataset'); state.missions=data.missions; populateDestinations(); updateOverview(data); applyFilters(); els.dataStatus.textContent=`Loaded ${data.missions.length} missions from the static JSON dataset.`; }catch(error){ els.body.innerHTML='<tr><td colspan="6" class="table-message">Mission data could not be loaded. Please run the project through a local web server.</td></tr>'; els.count.textContent='Data unavailable'; els.dataStatus.textContent='Data loading failed.'; console.error(error); } } function populateDestinations(){ [...new Set(state.missions.map(m=>m.destination))].sort().forEach(destination=>{ const option=document.createElement('option'); option.value=destination; option.textContent=destination; els.destination.append(option); }); } function updateOverview(data){ const missions=data.missions; els.total.textContent=missions.length; els.active.textContent=missions.filter(m=>m.status==='Active').length; els.completed.textContent=missions.filter(m=>m.status==='Completed').length; els.countries.textContent=new Set(missions.map(m=>m.country)).size; els.orbit.textContent=missions.filter(m=>m.status==='Active').length; els.updated.textContent=`Dataset updated ${formatDate(data.updated)}`; renderChart(missions); } function applyFilters(){ const term=els.search.value.trim().toLowerCase(), status=els.status.value, destination=els.destination.value; state.filtered=state.missions.filter(m=>(status==='all'||m.status===status)&&(destination==='all'||m.destination===destination)&&(!term||`${m.name} ${m.agency} ${m.destination}`.toLowerCase().includes(term))); sortMissions(); renderTable(); } function sortMissions(){ const mode=els.sort.value; state.filtered.sort((a,b)=>{ if(mode==='name-asc') return a.name.localeCompare(b.name); if(mode==='duration-desc') return b.durationDays-a.durationDays; const result=new Date(b.launchDate)-new Date(a.launchDate); return mode==='date-asc'?-result:result; }); } function renderTable(){ els.count.textContent=`${state.filtered.length} of ${state.missions.length} missions`; if(!state.filtered.length){els.body.innerHTML='<tr><td colspan="6" class="table-message">No missions match the selected filters.</td></tr>';return;} els.body.replaceChildren(...state.filtered.map(m=>{ const row=document.createElement('tr'); row.innerHTML=`<td><span class="mission-name">${escapeHTML(m.name)}</span><span class="mission-id">${escapeHTML(m.id)}</span></td><td>${escapeHTML(m.destination)}</td><td><span class="badge badge-${m.status.toLowerCase()}">${escapeHTML(m.status)}</span></td><td>${formatDate(m.launchDate)}</td><td>${m.durationDays} days</td><td>${escapeHTML(m.agency)}</td>`; return row; })); } function renderChart(missions){ const counts={}; missions.forEach(m=>counts[m.destination]=(counts[m.destination]||0)+1); const entries=Object.entries(counts).sort((a,b)=>b[1]-a[1]); const max=entries[0]?.[1]||1; els.chart.replaceChildren(...entries.map(([name,count])=>{ const row=document.createElement('div'); row.className='bar-row'; row.innerHTML=`<span>${escapeHTML(name)}</span><span class="bar-track"><span class="bar-fill" style="width:${count/max*100}%"></span></span><strong>${count}</strong>`; return row; })); } function formatDate(value){return new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value));} function escapeHTML(value){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));} [els.status,els.destination,els.sort].forEach(el=>el.addEventListener('change',applyFilters)); els.search.addEventListener('input',applyFilters); els.menu.addEventListener('click',()=>{const open=els.nav.classList.toggle('open');els.menu.setAttribute('aria-expanded',String(open));els.menu.querySelector('.sr-only').textContent=open?'Close menu':'Open menu';}); els.nav.addEventListener('click',e=>{if(e.target.matches('a')){els.nav.classList.remove('open');els.menu.setAttribute('aria-expanded','false');els.menu.querySelector('.sr-only').textContent='Open menu';}}); loadMissions();